FUNCTION_BLOCK FB_P16
VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL := FALSE;
    conveyorRight : BOOL := FALSE;
END_VAR
VAR
    (* State: 0 = idle, 1 = delivery, 2 = processing. *)
    state : USINT := 0;
    stepIndex : INT := 0;
    currentStation : USINT := 1;
    targetStation : USINT := 0;

    jobSequence : ARRAY[1..8] OF USINT;
    jobLength : INT := 0;
    inputLength : INT;
    i : INT;
    sequenceValid : BOOL;
    errorState : BOOL := FALSE;

    startupScans : USINT := 0;
    previousStart : BOOL := FALSE;
    startEdge : BOOL;
    targetPresent : BOOL;
    targetComplete : BOOL;

    (* Number of subsequent scans still prohibiting rightward motion. *)
    rightInhibitScans : USINT := 0;
END_VAR

(* One invocation represents one 20 ms scan.
   No reset input exists: errorState remains latched until FB reinitialization.
   Each accepted job snapshots its active sequence.
   C9 is implemented literally: EVERY leftward scan prohibits rightward
   motion during that scan and the following ten scans.
   Compilation and cycle-by-cycle functional verification are not claimed. *)

conveyorLeft := FALSE;
conveyorRight := FALSE;

startEdge := station1Start AND NOT previousStart;
previousStart := station1Start;

inputLength := USINT_TO_INT(processLength);
sequenceValid := (inputLength >= 1) AND (inputLength <= 8);

IF sequenceValid THEN
    FOR i := 1 TO inputLength DO
        IF (processSequence[i] < 1) OR (processSequence[i] > 5) THEN
            sequenceValid := FALSE;
        END_IF;

        (* Enforce the supplied sequence contract as well as K4. *)
        IF i = inputLength THEN
            IF processSequence[i] <> 5 THEN
                sequenceValid := FALSE;
            END_IF;
        ELSE
            IF (processSequence[i] < 2) OR
               (processSequence[i] > 4) THEN
                sequenceValid := FALSE;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF NOT sequenceValid THEN
    errorState := TRUE;
END_IF;

(* G[0,1]: the first two invocations cannot energize either output. *)
IF startupScans < 2 THEN
    startupScans := startupScans + 1;

ELSIF NOT errorState THEN
    CASE state OF
        0:
            IF startEdge AND sensor1 THEN
                jobLength := inputLength;
                FOR i := 1 TO jobLength DO
                    jobSequence[i] := processSequence[i];
                END_FOR;

                stepIndex := 1;
                currentStation := 1;
                targetStation := jobSequence[stepIndex];
                state := 1;
            END_IF;

        1:
            (* Delivery is evaluated below, including newly requested legs. *)

        2:
            targetPresent := FALSE;
            targetComplete := FALSE;

            CASE targetStation OF
                2:
                    targetPresent := sensor2;
                    targetComplete := station2Complete;
                3:
                    targetPresent := sensor3;
                    targetComplete := station3Complete;
                4:
                    targetPresent := sensor4;
                    targetComplete := station4Complete;
            ELSE
                errorState := TRUE;
            END_CASE;

            (* Completion is a level-qualified signal; both inputs must
               be TRUE in this scan. Only one process step advances. *)
            IF NOT errorState AND targetPresent AND targetComplete THEN
                IF stepIndex < jobLength THEN
                    stepIndex := stepIndex + 1;
                    targetStation := jobSequence[stepIndex];
                    state := 1;
                ELSE
                    errorState := TRUE;
                END_IF;
            END_IF;

    ELSE
        errorState := TRUE;
    END_CASE;

    IF (state = 1) AND NOT errorState THEN
        targetPresent := FALSE;

        CASE targetStation OF
            2: targetPresent := sensor2;
            3: targetPresent := sensor3;
            4: targetPresent := sensor4;
            5: targetPresent := sensor5;
        ELSE
            errorState := TRUE;
        END_CASE;

        IF NOT errorState THEN
            IF targetPresent THEN
                currentStation := targetStation;

                IF targetStation = 5 THEN
                    (* Delivery complete; another job needs a new start edge. *)
                    state := 0;
                    stepIndex := 0;
                    jobLength := 0;
                    targetStation := 0;
                ELSE
                    state := 2;
                END_IF;

            ELSIF targetStation < currentStation THEN
                conveyorLeft := TRUE;

            ELSIF targetStation > currentStation THEN
                IF rightInhibitScans = 0 THEN
                    conveyorRight := TRUE;
                END_IF;

            ELSE
                (* Consecutive equal stations require no transport.
                   Wait for that station's presence signal, then process
                   the distinct next step without skipping it. *)
                conveyorLeft := FALSE;
                conveyorRight := FALSE;
            END_IF;
        END_IF;
    END_IF;
END_IF;

(* Fault shutdown has priority over every operating state. *)
IF errorState THEN
    conveyorLeft := FALSE;
    conveyorRight := FALSE;
END_IF;

(* Update after output decisions: ten full scans after the last leftward
   output remain right-inhibited; rightward motion is allowed on scan 11. *)
IF conveyorLeft THEN
    rightInhibitScans := 10;
ELSIF rightInhibitScans > 0 THEN
    rightInhibitScans := rightInhibitScans - 1;
END_IF;

END_FUNCTION_BLOCK
